var tab;
type = getArguments('type');
var processedType = String(type).replace(/^\s+|\s+$/g, '').toLowerCase();
if (!type || type == "undefined") {
    tab = 3;
} else {
    switch(processedType) {
        case 'novel':
            tab = 3;
            break;
        case 'audio':
            tab = 2;
            break;
        case 'comic':
            tab = 8;
            break;
        case 'video':
            tab = 11;
            break;
        default:
            tab = 3;
            break;
    }
}
if (String(key).startsWith("m:") || String(key).startsWith("m：")) {
    tab = 8
    setArguments('type','comic')
    key = key.slice(2)
}
if (String(key).startsWith("t:") || String(key).startsWith("t：")) {
    tab = 2
    setArguments('type','audio')
    key = key.slice(2)
}
if (String(key).startsWith("d:") || String(key).startsWith("d：")) {
    tab = 11
    setArguments('type','video')
    key = key.slice(2)
}
if (String(key).startsWith("x:") || String(key).startsWith("x：")) {
    tab = 3
    setArguments('type','novel')
    key = key.slice(2)
}
if (key.length == 19 && !Number.isNaN(parseInt(key))) {
    result = source.key + '/api/detail?book_id=' + key
} else {
    result = source.key + '/api/search?key=' + encodeURI(java.put("key", key)) + '&offset=' + ((java.put("page", page) - 1) * 10) + '&tab_type=' + tab
}

