eval(String(source.bookSourceComment))


function getOptionUi(){
 // java.toast(source.getLoginUi())

 var UIArray = urlArray.map((item,index)=>{
  return {
       name:`${item.dec}`,
        type:"button",
       action:`setUi(${index})`
  }
 })
source.setLoginUi(JSON.stringify(UIArray))
}

function getUi(){
 var sz = source.getVariable();
 if(sz==null || sz==""){
   sz = -2
   source.setVariable(sz);
 }
if(Number(sz) == -2){
   java.toast('随机接口')
  }else if(Number(sz) == -1){
    java.toast('源计划正文解密')
  }else{
    java.toast(`${urlArray[Number(sz)].dec}:${urlArray[Number(sz)].url}`)
  }
}

function setUi(value){
  java.toast(value)
  source.setVariable(Number(value));
  if(Number(value) == -2){
   java.toast('随机接口')
  }else if(Number(value) == -1){
    java.toast('源计划正文解密')
  }else{
    java.toast(`${urlArray[Number(value)].dec}:${urlArray[Number(value)].url}`)
  }
}

exploreUrl:
@js:
sort=[];
burl = "https://novel.snssdk.com";
push=(title,url,type1,type2)=>sort.push({
		title: title,
		url: url,
		style: {
				layout_flexGrow: type1,
				layout_flexBasisPercent: type2
			}
	});

	$$=[["推荐","10"],["完结","11"],["热搜","12"],["黑马","13"],["爆更","15"]];
[["男频","1"],["女频","0"],["出版","2"]].map([title,id]=>{
	push('🔖'+title+'榜单🔖', null, 1, 1);
	if(id==2){ 	$$=$$.slice(1,$$.length-1) }
		$$.map([title,uri]=>{			
		 	url= burl + `/api/novel/channel/homepage/rank/rank_list/v2/?aid=13&app_name=news_article&app_version=9.7.3&channel=tengxun_tt&device_platform=android&os=android&device_type=ProjectTitan&os_api=29&os_version=10&openlive_plugin_status=1&isTTWebViewHeifSupport=0&limit=100&offset={{(page-1)*100}}&side_type=${uri}&type=${id}`;
				push(title, url, 1, 0.25);			
			});
	});

	category = () =>{
			category_url = burl + "/api/novel/channel/homepage/new_category/page/data/v1/?aid=13";
return JSON.parse(java.ajax(category_url)).data		
		}

 json = (data) => {
 boy = data.boy_category;
 girl = data.girl_category;
 publish = data.publish_category;
 json = [["男频","gender=1",boy],["女频","gender=0",girl],["出版","genre_type=160",publish]];
 return JSON.parse(JSON.stringify(json));
 }	

		json(category()).map([tit1,gender,category]=>{
	 push('🔖'+tit1+'🔖', null, 1, 1);
 category.map(($,index)=>{
 	index++;
	 title = $.category_name;
 	cid = $.category_id;
	 url= burl + `/api/novel/channel/homepage/new_category/book_list/v1/?aid=1967&app_name=news_article&app_version=9.7.3&channel=tengxun_tt&creation_status=9&device_platform=android&enter_from=novel_category&novel_host&novel_version&version_code=973&version_name=9.7.3&word_count=9&os=android&device_type=ProjectTitan&os_api=29&os_version=10&offset={{(page-1)*100}}&limit=100&category_id=${cid}&${gender}`;

 	if(index <= category.length - category.length%3)
			 {	push(title, url, 1, 0.25);}
				else{ push(title, url, 0, 0.29);}
 });
 });
JSON.stringify(sort);

